# One line: a relation
var line_a_start: Vector3 = Vector3(0, 0, -0.2)
var line_a_end: Vector3 = Vector3(0, 0, 0.2)

# Two lines: a question
var line_b_start: Vector3 = Vector3(0, -0.2, 0)
var line_b_end: Vector3 = Vector3(0, 0.2, 0)

# Are they perpendicular?
# Are they crossing at their midpoints?
# The puzzle checks both.

func _setup_target_markers() -> void:
	for i in range(target_positions.size()):
		var marker = _create_alyx_marker(i)
		add_child(marker)
		marker.global_position = global_transform * target_positions[i]
		target_markers.append(marker)

func _create_alyx_marker(_index: int) -> Node3D:
	var marker = Node3D.new()

	# Torus ring — the snap target
	var ring_mesh = MeshInstance3D.new()
	var torus = TorusMesh.new()
	torus.inner_radius = 0.018
	torus.outer_radius = 0.025
	torus.rings = 24
	ring_mesh.mesh = torus

	var mat = StandardMaterial3D.new()
	mat.albedo_color = Color(0.0, 0.8, 1.0, 0.6)  # Cyan hologram
	mat.emission_enabled = true
	mat.emission = Color(0.0, 0.8, 1.0)
	mat.emission_energy_multiplier = 1.5
	mat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	ring_mesh.material_override = mat
	marker.add_child(ring_mesh)

	return marker

class FormConstraint:
	var type: String  # "perpendicular", "parallel", "intersect_center"
	var line_a_index: int
	var line_b_index: int
	var tolerance: float

	static func plus_constraints() -> Array[FormConstraint]:
		# Plus shape requires:
		# 1. Lines must be perpendicular (dot product = 0)
		# 2. Lines must intersect at their midpoints
		return [
			FormConstraint.new("perpendicular", 0, 1, 0.15),
			FormConstraint.new("intersect_center", 0, 1, 0.08)
		]

func _check_perpendicular(line_a: SnapLineSegment, line_b: SnapLineSegment, tolerance: float) -> bool:
	var dir_a = (line_a.end_pos - line_a.start_pos).normalized()
	var dir_b = (line_b.end_pos - line_b.start_pos).normalized()
	var dot = abs(dir_a.dot(dir_b))
	return dot < tolerance  # Zero means perpendicular

func _on_endpoint_near_target(endpoint: Node3D, target_index: int) -> void:
	var target_pos = global_transform * target_positions[target_index]
	var dist = endpoint.global_position.distance_to(target_pos)

	if dist < snap_distance:
		# Snap!
		endpoint.global_position = target_pos
		line_snapped_to_target.emit(snap_lines[0])
		_check_completion()

func _check_completion() -> void:
	if is_completed:
		return

	# All endpoints at targets?
	if require_all_at_targets and not _all_endpoints_at_targets():
		return

	# Form constraints satisfied?
	if use_form_constraints:
		for constraint in form_constraints:
			if not _evaluate_constraint(constraint):
				return

	# Puzzle complete!
	is_completed = true
	puzzle_completed.emit()
	_complete_puzzle()

func _complete_puzzle() -> void:
	# Lock lines in place
	if lock_on_complete:
		for line in snap_lines:
			line.lock()

	# Green completion pulse
	for line in snap_lines:
		line.set_color(completion_color)  # Cyan → Green

	# Pulse animation
	var tween = create_tween()
	for marker in target_markers:
		tween.parallel().tween_property(
			marker, "scale",
			Vector3.ONE * 1.5, completion_pulse_duration
		)

	# Trigger map action (e.g. remove floor cube)
	if trigger_tag and trigger_action:
		_trigger_tag_action(trigger_tag, trigger_action)
